create or replace function public.preview_schedule_swap_v1(p_left_id uuid,p_right_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a teacher_schedule%rowtype;b teacher_schedule%rowtype;ok boolean:=false;msg text;begin perform open_permission_context('schedule.edit');if p_left_id=p_right_id then return jsonb_build_object('ok',false,'error','SAME_SCHEDULE_ROW');end if;select * into a from teacher_schedule where id=p_left_id and active and institution_code=current_tenant_code();select * into b from teacher_schedule where id=p_right_id and active and institution_code=current_tenant_code();if a.id is null or b.id is null then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND');end if;if a.locked or b.locked then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_LOCKED');end if;begin update teacher_schedule set active=false where id in(a.id,b.id);perform upsert_schedule_slot_permission_core_v2(a.teacher_assignment_id,b.weekday,b.period,a.classroom_id,a.subgroup_id,a.id,false,'manual');perform upsert_schedule_slot_permission_core_v2(b.teacher_assignment_id,a.weekday,a.period,b.classroom_id,b.subgroup_id,b.id,false,'manual');ok:=true;raise exception using errcode='P0001',message='OKULOS_PREVIEW_ROLLBACK';exception when others then if SQLERRM='OKULOS_PREVIEW_ROLLBACK' and ok then return jsonb_build_object('ok',true,'left_id',a.id,'right_id',b.id);else msg:=SQLERRM;return jsonb_build_object('ok',false,'error',msg);end if;end;end$$;
create or replace function public.swap_schedule_slots_v1(p_left_id uuid,p_right_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a teacher_schedule%rowtype;b teacher_schedule%rowtype;begin perform open_permission_context('schedule.edit');if p_left_id=p_right_id then raise exception 'SAME_SCHEDULE_ROW';end if;select * into a from teacher_schedule where id=p_left_id and active and institution_code=current_tenant_code() for update;select * into b from teacher_schedule where id=p_right_id and active and institution_code=current_tenant_code() for update;if a.id is null or b.id is null then raise exception 'SCHEDULE_ROW_NOT_FOUND';end if;if a.locked or b.locked then raise exception 'SCHEDULE_ROW_LOCKED';end if;perform create_schedule_restore_point('Elle takas öncesi','Ders programı güvenli takas geri dönüş noktası');update teacher_schedule set active=false where id in(a.id,b.id);perform upsert_schedule_slot_permission_core_v2(a.teacher_assignment_id,b.weekday,b.period,a.classroom_id,a.subgroup_id,a.id,false,'manual');perform upsert_schedule_slot_permission_core_v2(b.teacher_assignment_id,a.weekday,a.period,b.classroom_id,b.subgroup_id,b.id,false,'manual');return jsonb_build_object('ok',true,'left_id',a.id,'right_id',b.id);end$$;
revoke all on function public.preview_schedule_swap_v1(uuid,uuid) from public;grant execute on function public.preview_schedule_swap_v1(uuid,uuid) to authenticated;
revoke all on function public.swap_schedule_slots_v1(uuid,uuid) from public;grant execute on function public.swap_schedule_slots_v1(uuid,uuid) to authenticated;
